/* Translation memory: every run of words an open translation model (LibreTranslate, or Hugging Face's opus-mt and NLLB) has translated, kept for good, so the same words are never sent twice: "Add to cart" into French is translated once for every store, a website translated again after a small edit sends only the new words, and a language translated after a failure picks up where it stopped. Keyed by the languages and the sha256 of the words; the words themselves are kept beside it for checking. Only website text that is already public goes in, never a customer's details. Server only. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.translation_memory ( source_lang text NOT NULL CHECK (length(source_lang) BETWEEN 2 AND 12), target_lang text NOT NULL CHECK (length(target_lang) BETWEEN 2 AND 12), source_hash text NOT NULL CHECK (source_hash ~ '^[0-9a-f]{64}$'), source_text text NOT NULL CHECK (length(source_text) <= 20000), translated text NOT NULL CHECK (length(translated) <= 40000), provider text NOT NULL DEFAULT 'libretranslate' CHECK (provider IN ('libretranslate', 'huggingface', 'llm', 'mymemory', 'openai')), created_at timestamptz NOT NULL DEFAULT now(), used_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (source_lang, target_lang, source_hash) );
ALTER TABLE public.translation_memory DROP CONSTRAINT IF EXISTS translation_memory_provider_check;
ALTER TABLE public.translation_memory ADD CONSTRAINT translation_memory_provider_check CHECK (provider IN ('libretranslate', 'huggingface', 'llm', 'mymemory', 'openai'));
ALTER TABLE public.translation_memory ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.translation_memory FROM anon, authenticated;
notify pgrst, 'reload schema';
